/* @autogenerated */
package net.civeira.phylax.features.oauth.tokensecurity.application.usecase;

import java.util.Map;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.common.exception.NotAllowedException;
import net.civeira.phylax.features.oauth.tokensecurity.domain.TokenIntrospectionResult;
import net.civeira.phylax.features.oauth.tokensecurity.domain.gateway.TokenLookupGateway;
import net.civeira.phylax.features.oauth.tokensecurity.domain.gateway.TokenSigner;

/**
 * Application use case for RFC 7662 token introspection.
 *
 * Responsibilities: - Verify the JWT signature of the presented token. - Delegate to
 * {@link TokenLookupGateway} to confirm the token is not revoked or expired in the session store. -
 * Build the {@link TokenIntrospectionResult} returned to the caller.
 *
 * Design notes: - Signature verification is done first; an invalid JWT short-circuits to inactive.
 * - JTI-based lookup handles JWT tokens; raw-token lookup handles opaque tokens. - Client
 * credential validation is the controller's responsibility.
 */
@Slf4j
@ApplicationScoped
@RequiredArgsConstructor
public class IntrospectTokenUseCase {

  /**
   * Token signer used for JWT signature and payload verification.
   */
  private final TokenSigner tokenSigner;

  /**
   * Gateway used to look up active sessions by JTI or raw token.
   */
  private final TokenLookupGateway tokenLookupGateway;

  /**
   * Introspects a token and returns its active status and metadata.
   *
   * Verifies the JWT signature first; an invalid or expired JWT immediately yields an inactive
   * result. For valid JWTs the JTI claim is used to query the session store, which also handles
   * revocation and server-side expiry. Opaque tokens fall back to a raw-token lookup.
   *
   * @param tenant tenant identifier
   * @param rawToken raw token string presented by the caller
   * @return introspection result (active or inactive)
   */
  public TokenIntrospectionResult introspect(String tenant, String rawToken) {
    if (rawToken == null || rawToken.isBlank()) {
      return TokenIntrospectionResult.inactive();
    }

    Map<String, Object> payload;
    try {
      payload = tokenSigner.verifyTokenPayload(tenant, rawToken);
    } catch (NotAllowedException e) {
      log.debug("Token signature verification failed for tenant {}", tenant);
      return TokenIntrospectionResult.inactive();
    }

    if (payload.isEmpty()) {
      return TokenIntrospectionResult.inactive();
    }

    Object jtiObj = payload.get("jti");
    if (jtiObj != null) {
      String jti = String.valueOf(jtiObj);
      return tokenLookupGateway.lookupByJti(tenant, jti)
          .orElse(TokenIntrospectionResult.inactive());
    }

    return tokenLookupGateway.lookupByRawToken(tenant, rawToken)
        .orElse(TokenIntrospectionResult.inactive());
  }
}
